metadata.content:
Implement Phase 1 first: honest progress messaging, no backend job system yet.
Bashcat > /tmp/korelumina_honest_import_progress_patch.py <<'PY'
from pathlib import Path

path = Path(
    "apps/lumina-builder/src/components/import/ImportModal.tsx"
)

text = path.read_text(encoding="utf-8")

old = '''type StageKey = "connect" | "fetch" | "analyze" | "finalize";
const STAGES: { key: StageKey; label: string; pct: number }[] = [
  { key: "connect",  label: "Connecting to source",   pct: 18 },
  { key: "fetch",    label: "Fetching files",         pct: 62 },
  { key: "analyze",  label: "Analyzing project",      pct: 88 },
  { key: "finalize", label: "Finalizing workspace",   pct: 100 },
];
'''

new = '''type StageKey = "connect" | "clone" | "metadata" | "finalize";

const STAGES: { key: StageKey; label: string; pct: number }[] = [
  { key: "connect",  label: "Connecting to GitHub",        pct: 18 },
  { key: "clone",    label: "Cloning repository",          pct: 62 },
  { key: "metadata", label: "Reading project metadata",    pct: 88 },
  { key: "finalize", label: "Finalizing workspace",        pct: 100 },
];

const LONG_IMPORT_DELAY_MS = 10_000;
'''
if old not in text:
    raise SystemExit("ERROR: STAGES block not found")

text = text.replace(old, new)

old = '''  const [completedAt, setCompletedAt] = useState<number | null>(null);
'''

new = '''  const [completedAt, setCompletedAt] = useState<number | null>(null);
  const [longImportNotice, setLongImportNotice] = useState(false);
'''
if old not in text:
    raise SystemExit("ERROR: completedAt state not found")

text = text.replace(old, new)

old = '''  useEffect(() => () => {
    timers.current.forEach((arr) => arr.forEach(clearTimeout));
    timers.current.clear();
  }, []);
'''

new = '''  useEffect(() => () => {
    timers.current.forEach((arr) => arr.forEach(clearTimeout));
    timers.current.clear();
  }, []);

  useEffect(() => {
    if (progress?.status !== "running") {
      setLongImportNotice(false);
      return;
    }

    const timer = window.setTimeout(() => {
      setLongImportNotice(true);
    }, LONG_IMPORT_DELAY_MS);

    return () => {
      window.clearTimeout(timer);
    };
  }, [progress?.status, progress?.label]);
'''
if old not in text:
    raise SystemExit("ERROR: cleanup effect not found")

text = text.replace(old, new)

text = text.replace(
'''          stage: "fetch",
          pct: STAGES[1].pct,
          message: STAGES[1].label,
''',
'''          stage: "clone",
          pct: STAGES[1].pct,
          message: STAGES[1].label,
'''
)

text = text.replace(
'''          stage: "analyze",
          pct: STAGES[2].pct,
          message: STAGES[2].label,
''',
'''          stage: "metadata",
          pct: STAGES[2].pct,
          message: STAGES[2].label,
'''
)

old = '''              <ProgressPanel progress={progress} onRetry={submitUrl} onCancel={reset} onClose={close} />
'''

new = '''              <ProgressPanel
                progress={progress}
                longImportNotice={longImportNotice}
                onRetry={submitUrl}
                onCancel={reset}
                onClose={close}
              />
'''
if old not in text:
    raise SystemExit("ERROR: ProgressPanel render not found")

text = text.replace(old, new)

old = '''function ProgressPanel({
  progress, onRetry, onCancel, onClose,
}: { progress: Progress; onRetry: () => void; onCancel: () => void; onClose: () => void }) {
'''

new = '''function ProgressPanel({
  progress,
  longImportNotice,
  onRetry,
  onCancel,
  onClose,
}: {
  progress: Progress;
  longImportNotice: boolean;
  onRetry: () => void;
  onCancel: () => void;
  onClose: () => void;
}) {
'''
if old not in text:
    raise SystemExit("ERROR: ProgressPanel signature not found")

text = text.replace(old, new)

old = '''      {error && (
        <div className="rounded-lg border border-rose-500/30 bg-rose-500/10 p-3 text-[12px] text-rose-200">
          {error}
        </div>
      )}
'''

new = '''      {longImportNotice && status === "running" && (
        <div className="rounded-lg border border-gold/30 bg-gold/10 p-3 text-[12px] text-gold/90 leading-relaxed">
          Large repositories can take up to a minute. KoreLumina is still importing your project and will continue automatically when the repository clone finishes.
        </div>
      )}

      {error && (
        <div className="rounded-lg border border-rose-500/30 bg-rose-500/10 p-3 text-[12px] text-rose-200">
          {error}
        </div>
      )}
'''
if old not in text:
    raise SystemExit("ERROR: error block not found")

text = text.replace(old, new)

path.write_text(text, encoding="utf-8")

print("honest import progress messaging patch applied")
PY

python3 /tmp/korelumina_honest_import_progress_patch.py

npm --workspace lumina-builder run build
After build passes, test one import. Expected UI wording:


Connecting to GitHub


Cloning repository


Reading project metadata


Finalizing workspace


If it takes longer than 10 seconds, it should show the large-repo notice instead of looking frozen.
